using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking change: EF Core 9 throws if Migrate() is called inside a user transaction.
    // Migrations manage their own transactions internally.
    // Fix: remove the explicit wrapping transaction around Migrate().
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

