using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder==",
            "ShopDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // Breaking change: EF Core 9 Cosmos provider renamed the default
            // discriminator property from "Discriminator" to "$type".
            // Existing documents use "Discriminator". We must explicitly configure
            // the old property name to avoid a schema mismatch at runtime.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class ProductService
{
    // Breaking change: EF Core 9 Cosmos provider removed synchronous query support.
    // Calls like .ToList(), .First(), .Count() etc. now throw
    // InvalidOperationException at runtime.
    // Fix: use async equivalents (ToListAsync, FirstAsync, CountAsync, etc.)
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products
            .Where(p => p.Category == "Electronics")
            .ToListAsync();
    }

    async Task<Product> GetFirstProductAsync(CosmosDbContext db)
    {
        return await db.Products.FirstAsync();
    }

    async Task<int> CountProductsAsync(CosmosDbContext db)
    {
        return await db.Products.CountAsync();
    }
}

